def transform(g, fill=2):
    h=len(g);w=len(g[0]);shape=4
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]==shape]
    r0=min(p[0] for p in pts);r1=max(p[0] for p in pts)
    c0=min(p[1] for p in pts);c1=max(p[1] for p in pts)
    out=[r[:] for r in g]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if (i in(r0,r1) or j in(c0,c1)) and out[i][j]!=shape:
                out[i][j]=fill
    return out
